import {sealJournal,openJournal,validateEntries} from './crypto.mjs';
const $=id=>document.getElementById(id);
const moods={happy:'기쁨',calm:'평온',ordinary:'보통',sad:'슬픔',tired:'피곤'};
let backend,user=null,pass='',entries=[],cloud=null,selected=null,dirty=false,busy=false,generation=0,month=new Date(),dateFilter='',toastTimer;
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function text(tag,cls,value){const n=document.createElement(tag);n.className=cls;n.textContent=value;return n;}
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function errorMessage(e){const code=e?.code||'';if(code.includes('popup-closed')||code.includes('cancelled-popup'))return '로그인을 취소했어요.';if(code.includes('popup-blocked'))return '팝업이 차단됐어요. 이 사이트의 로그인 팝업을 허용해 주세요.';if(code.includes('unauthorized-domain'))return '이 사이트의 도메인이 Firebase 로그인에 등록되지 않았어요.';if(code.includes('permission-denied'))return '접근 권한이 없어요. 로그인과 보안 규칙을 확인해 주세요.';if(code.includes('unavailable')||code.includes('network-request-failed'))return '네트워크 연결을 확인해 주세요. 입력 내용은 유지됩니다.';if(e?.name==='OperationError')return '일기 암호가 다르거나 암호화 기록이 손상됐어요.';if(e?.name==='Error'&&/일기|암호화|로그인 상태/.test(e.message))return e.message;if(code==='conflict')return '다른 창에서 기록을 변경했어요. 입력을 복사해 둔 뒤 새로고침해 주세요.';return e?.safeMessage||'처리하지 못했어요. 입력과 연결 상태를 확인해 주세요. 기존 기록은 그대로입니다.';}
function currentSession(g,uid){return generation===g&&user?.uid===uid;}
function checkSession(g,uid){if(generation!==g||!user||user.uid!==uid)throw Object.assign(Error(),{safeMessage:'로그인 상태가 바뀌었어요. 다시 열어 주세요.'});}
function setBusy(value){busy=value;document.querySelectorAll('#journal button,#journal input,#journal textarea,#journal select,#unlock-form button,#unlock-form input,#login,#gate-logout').forEach(e=>e.disabled=value);}
function clearPrivate(){generation++;pass='';entries=[];cloud=null;selected=null;dirty=false;$('entryTitle').value='';$('entryBody').value='';$('entryDate').value='';$('search').value='';$('diary-password').value='';$('confirm-password').value='';$('entryList').replaceChildren();$('calendarDays').replaceChildren();$('journal').hidden=true;$('gate').hidden=false;$('unlock-panel').hidden=true;$('unlock-form').hidden=false;$('entryMood').value='ordinary';$('totalCount').textContent=$('monthCount').textContent=$('navCount').textContent=$('listCount').textContent='0';$('login').hidden=false;$('auth-error').textContent='';}
function discard(){return !dirty||confirm('저장하지 않은 내용이 있어요. 이 내용을 버리고 계속할까요?');}
function fill(entry){selected=entry?.id||null;$('entryDate').value=entry?.date||today();$('entryTitle').value=entry?.title||'';$('entryBody').value=entry?.body||'';$('entryMood').value=entry?.mood||'ordinary';$('deleteEntry').hidden=!entry;dirty=false;$('saveState').textContent=entry?'저장된 기록':'새로운 기록';$('charCount').textContent=$('entryBody').value.length.toLocaleString()+'자';render();}
function render(){const query=$('search').value.toLocaleLowerCase();const visible=entries.filter(e=>(!dateFilter||e.date===dateFilter)&&(!$('moodFilter').value||e.mood===$('moodFilter').value)&&(!query||(e.title+' '+e.body).toLocaleLowerCase().includes(query))).sort((a,b)=>b.date.localeCompare(a.date));$('entryList').replaceChildren();for(const entry of visible){const b=text('button','entry-card'+(selected===entry.id?' active':''),'');b.type='button';b.append(text('small','',entry.date+' · '+moods[entry.mood]),text('strong','',entry.title||'제목 없는 하루'),text('p','',entry.body.slice(0,70)));b.onclick=()=>{if(!busy&&discard())fill(entry);};$('entryList').append(b);}if(!visible.length)$('entryList').append(text('p','empty','아직 기록이 없어요. 오늘의 이야기를 남겨 보세요.'));$('navCount').textContent=entries.length;$('totalCount').textContent=entries.length;$('listCount').textContent=visible.length;$('monthCount').textContent=entries.filter(e=>e.date.startsWith(today().slice(0,7))).length;calendar();}
function calendar(){const year=month.getFullYear(),m=month.getMonth();$('monthLabel').textContent=`${year}년 ${m+1}월`;$('calendarDays').replaceChildren();for(let i=0;i<new Date(year,m,1).getDay();i++)$('calendarDays').append(text('span','',''));for(let day=1;day<=new Date(year,m+1,0).getDate();day++){const date=`${year}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const has=entries.some(e=>e.date===date);const b=text('button',(has?'has-entry ':'')+(dateFilter===date?'selected':''),String(day));b.type='button';b.setAttribute('aria-label',date+(has?' 기록 있음':''));b.onclick=()=>{if(!busy){dateFilter=dateFilter===date?'':date;render();}};$('calendarDays').append(b);}}
async function saveEntries(next){if(!user||!pass)throw Error('locked');const g=generation,uid=user.uid,expected=cloud?.version||0;const envelope=await sealJournal(validateEntries(next),pass,uid);checkSession(g,uid);const version=await backend.write(uid,envelope,expected);checkSession(g,uid);cloud={version,envelope};entries=next;}
$('login').onclick=async()=>{if(!backend||busy)return;const g=generation;$('auth-error').textContent='';try{await backend.login();}catch(e){if(g===generation)$('auth-error').textContent=errorMessage(e);}};
$('unlock-form').onsubmit=async e=>{e.preventDefault();if(busy||!user)return;setBusy(true);$('auth-error').textContent='';const g=generation,uid=user.uid;try{const candidate=$('diary-password').value;if(!cloud&&candidate!==$('confirm-password').value)throw Object.assign(Error(),{safeMessage:'새 일기 암호가 서로 달라요.'});const next=cloud?await openJournal(cloud.envelope,candidate,uid):[];checkSession(g,uid);if(!cloud){const envelope=await sealJournal([],candidate,uid);checkSession(g,uid);const version=await backend.write(uid,envelope,0);checkSession(g,uid);cloud={version,envelope};}pass=candidate;entries=next;$('diary-password').value=$('confirm-password').value='';$('gate').hidden=true;$('journal').hidden=false;dateFilter='';fill(null);}catch(e){if(currentSession(g,uid))$('auth-error').textContent=errorMessage(e);}finally{if(currentSession(g,uid))setBusy(false);}};
async function logout(){if(busy||!discard())return;clearPrivate();user=null;try{await backend.logout();}catch{notify('화면은 잠겼지만 로그아웃 확인에 실패했어요. 탭을 닫아 주세요.');}}
$('gate-logout').onclick=logout;$('lock').onclick=logout;
$('entryForm').addEventListener('input',()=>{dirty=true;$('saveState').textContent='저장하지 않은 변경';$('charCount').textContent=$('entryBody').value.length.toLocaleString()+'자';});
$('entryForm').onsubmit=async e=>{e.preventDefault();if(busy||!pass)return;const g=generation,uid=user.uid;setBusy(true);try{const nextEntry={id:selected||crypto.randomUUID(),date:$('entryDate').value,title:$('entryTitle').value,body:$('entryBody').value,mood:$('entryMood').value};const next=[...entries.filter(x=>x.id!==nextEntry.id),nextEntry];validateEntries(next);await saveEntries(next);dirty=false;fill(nextEntry);notify('암호화해 저장했어요.');}catch(e){if(currentSession(g,uid))notify(errorMessage(e));}finally{if(currentSession(g,uid))setBusy(false);}};
$('deleteEntry').onclick=async()=>{if(busy||!selected||!confirm('이 일기를 삭제할까요? 먼저 암호화 백업을 보관할 수 있어요.'))return;const g=generation,uid=user.uid;setBusy(true);try{await saveEntries(entries.filter(e=>e.id!==selected));dirty=false;fill(null);notify('일기를 삭제했어요.');}catch(e){if(currentSession(g,uid))notify(errorMessage(e));}finally{if(currentSession(g,uid))setBusy(false);}};
$('newEntry').onclick=()=>{if(!busy&&discard()){dateFilter='';fill(entries.find(e=>e.date===today())||null);}};$('allEntries').onclick=()=>{dateFilter='';render();};$('search').oninput=render;$('moodFilter').onchange=render;
$('prevMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);calendar();};$('nextMonth').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);calendar();};$('todayButton').onclick=()=>{$('entryDate').value=today();dirty=true;$('saveState').textContent='저장하지 않은 변경';};
$('refresh').onclick=async()=>{if(busy||!discard()||!user)return;setBusy(true);const g=generation,uid=user.uid;try{const latest=await backend.read(uid);if(!latest)throw Error('missing journal');const next=await openJournal(latest.envelope,pass,uid);checkSession(g,uid);cloud=latest;entries=next;fill(null);notify('최신 기록을 불러왔어요.');}catch(e){if(currentSession(g,uid))notify(errorMessage(e));}finally{if(currentSession(g,uid))setBusy(false);}};
$('backup').onclick=()=>{if(busy||!cloud)return;const blob=new Blob([JSON.stringify({format:'haru-journal-backup-v1',envelope:cloud.envelope})],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='haru-encrypted-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(dirty?'저장된 기록만 백업했어요. 미저장 입력은 포함되지 않습니다.':'암호화 백업을 저장했어요.');};
$('restore').onclick=()=>{if(!busy)$('backupFile').click();};$('backupFile').onchange=async()=>{const file=$('backupFile').files[0];$('backupFile').value='';if(!file||busy||!user)return;if(file.size>720000){notify('백업은 720KB 이하여야 해요.');return;}if(!confirm('현재 기록 전체를 이 백업으로 교체할까요? 기존 기록을 먼저 백업해 주세요.'))return;setBusy(true);const g=generation,uid=user.uid;try{const data=JSON.parse(await file.text());if(data.format!=='haru-journal-backup-v1')throw Error('format');const next=await openJournal(data.envelope,pass,uid);checkSession(g,uid);await saveEntries(next);dirty=false;fill(null);notify('백업을 복원했어요.');}catch(e){if(currentSession(g,uid))notify(errorMessage(e));}finally{if(currentSession(g,uid))setBusy(false);}};
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='s'&&!$('journal').hidden){e.preventDefault();if(!busy)$('entryForm').requestSubmit();}});
$('todayLabel').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());
try{const {createBackend}=await import('./firebase.mjs');backend=await createBackend();backend.onUser(async current=>{clearPrivate();user=current;setBusy(false);if(!current)return;$('login').hidden=true;$('account-status').textContent='Google 계정에 로그인했어요. 일기 암호로 열어 주세요.';$('setup-note').textContent='암호화 기록을 확인하고 있어요.';setBusy(true);const g=generation,uid=current.uid;try{const latest=await backend.read(uid);checkSession(g,uid);cloud=latest;$('unlock-panel').hidden=false;$('new-vault-panel').hidden=!!latest;$('confirm-password').required=!latest;$('unlock').textContent=latest?'일기장 열기':'암호화 일기장 만들기';$('setup-note').textContent='';}catch(e){if(currentSession(g,uid)){$('auth-error').textContent=errorMessage(e);$('unlock-panel').hidden=false;$('unlock-form').hidden=true;}}finally{if(currentSession(g,uid))setBusy(false);}});}catch{$('login').disabled=true;$('setup-note').textContent='Firebase 연결이 준비되지 않았어요. 서비스 설정 후 사용할 수 있습니다.';}
